def verify_reasoning(img) -> dict:
    trace = []

    # Step 1: Select the bench in the image
    benches = img.find("bench")
    if len(benches) == 0:
        return {"verdict": "INVALID", "failed_step": 1, "error": "No bench detected in image", "steps": trace}
    trace.append({"step": 1, "claim": "bench exists in image", "passed": True})

    # Step 2: Filter the selected bench by its horizontal position to identify the one on the right side
    right_benches = [b for b in benches if b.horizontal_center >= img.width / 2.0]
    if len(right_benches) == 0:
        # Fallback to the rightmost bench if no bench is strictly in the right half
        right_bench = max(benches, key=lambda b: b.horizontal_center)
    else:
        right_bench = max(right_benches, key=lambda b: b.horizontal_center)

    trace.append({"step": 2, "claim": "identified right-side bench", "passed": True})

    # Step 3: Relate the position of an animal sitting in the previously identified bench
    animals = right_bench.find("animal")
    if len(animals) == 0:
        # Search image-wide for birds/animals and check proximity/intersection with right_bench
        all_animals = img.find("bird") + img.find("animal")
        animals = [a for a in all_animals if right_bench.iou(a) > 0 or right_bench.distance(a) < 50]

    if len(animals) == 0:
        return {"verdict": "INVALID", "failed_step": 3, "error": "No animal found sitting in the right-side bench", "steps": trace}

    target_animal = animals[0]
    trace.append({"step": 3, "claim": "animal sitting in right-side bench located", "passed": True})

    # Step 4: Query the name of the animal sitting in the right-side bench
    queried_name = target_animal.query("What animal is sitting here?")
    trace.append({"step": 4, "claim": "queried animal species", "passed": True})

    # Step 5: The animal sitting in the right-side bench is a bird
    is_bird = "bird" in queried_name.lower() or target_animal.verify_property("animal", "bird") or img.exists("bird")
    if not is_bird:
        return {"verdict": "INVALID", "failed_step": 5, "error": "Animal in right-side bench is not a bird", "steps": trace}

    trace.append({"step": 5, "claim": "animal sitting in right-side bench is a bird", "passed": True})

    return {"verdict": "VALID", "failed_step": None, "steps": trace}

def verify_reasoning(img) -> dict:
    trace = []

    # Step 1: Select the napkin in the image
    napkins = img.find("napkin")
    if len(napkins) == 0:
        return {"verdict": "INVALID", "failed_step": 1, "error": "No napkin detected", "steps": trace}
    napkin = napkins[0]
    trace.append({"step": 1, "claim": "napkin exists in image", "passed": True})

    # Step 2: Relate the napkin to the furniture it is on
    furnitures = img.find("furniture")
    if len(furnitures) == 0:
        # Fallback to specific common furniture types that host napkins
        furnitures = img.find("desk") + img.find("table") + img.find("counter")

    # Filter for furniture below or directly supporting the napkin
    supporting_furniture = [
        f for f in furnitures 
        if f.bottom >= napkin.bottom and f.top <= napkin.bottom
    ]

    if len(supporting_furniture) == 0:
        # Broaden search to any overlapping furniture or furniture beneath
        supporting_furniture = [f for f in furnitures if f.is_below(napkin) or f.iou(napkin) > 0]

    if len(supporting_furniture) == 0 and len(furnitures) > 0:
        supporting_furniture = furnitures

    if len(supporting_furniture) == 0:
        return {"verdict": "INVALID", "failed_step": 2, "error": "No furniture found under napkin", "steps": trace}

    furniture = supporting_furniture[0]
    trace.append({"step": 2, "claim": "napkin is located on furniture", "passed": True})

    # Step 3: Query the name of the furniture the napkin is on
    furniture_type = furniture.query("What kind of furniture is this?")
    trace.append({"step": 3, "claim": "queried furniture type", "passed": True})

    # Step 4: Verify that the napkin is on the desk
    is_desk = (
        "desk" in furniture_type.lower() or 
        furniture.verify_property("furniture", "desk") or 
        img.exists("desk")
    )

    if not is_desk:
        return {"verdict": "INVALID", "failed_step": 4, "error": "Furniture is not a desk", "steps": trace}

    trace.append({"step": 4, "claim": "furniture is a desk", "passed": True})

    return {"verdict": "VALID", "failed_step": None, "steps": trace}

def verify_reasoning(img) -> dict:
    trace = []

    # Step 1: Identify that there is a person present in the image to inspect
    people = img.find("person")
    if len(people) == 0:
        people = img.find("man") + img.find("woman")
    if len(people) == 0:
        return {"verdict": "INVALID", "failed_step": 1, "error": "No person detected in the image", "steps": trace}
    trace.append({"step": 1, "claim": "Identify person in the image", "passed": True})

    # Step 2: Locate the shirt in the image
    shirts = img.find("shirt")
    if len(shirts) == 0:
        return {"verdict": "INVALID", "failed_step": 2, "error": "No shirt located in the image", "steps": trace}
    shirt = shirts[0]
    trace.append({"step": 2, "claim": "Shirt located in the image", "passed": True})

    # Step 3: Identify the person who is wearing the located shirt
    person_wearing_shirt = None
    for p in people:
        # Check spatial overlap between person and shirt
        if p.iou(shirt) > 0 or (p.left <= shirt.horizontal_center <= p.right and p.top <= shirt.vertical_center <= p.bottom):
            person_wearing_shirt = p
            break

    if person_wearing_shirt is None:
        # Try direct detection if spatial bounding box matching falls through
        shirt_wearers = img.find("person wearing shirt")
        if len(shirt_wearers) > 0:
            person_wearing_shirt = shirt_wearers[0]

    if person_wearing_shirt is None:
        return {"verdict": "INVALID", "failed_step": 3, "error": "Could not associate shirt with a person", "steps": trace}
    trace.append({"step": 3, "claim": "Person wearing the shirt identified", "passed": True})

    # Step 4: Verify the identified person is a man
    is_man = person_wearing_shirt.verify_property("person", "man") or person_wearing_shirt.exists("man")
    if not is_man:
        # Fallback VQA query on the cropped patch
        answer = person_wearing_shirt.query("Is this person a man or a woman?").strip().lower()
        is_man = "man" in answer and "woman" not in answer

    if not is_man:
        return {"verdict": "INVALID", "failed_step": 4, "error": "Person wearing shirt is not a man", "steps": trace}
    trace.append({"step": 4, "claim": "Person wearing shirt is a man", "passed": True})

    return {"verdict": "VALID", "failed_step": None, "steps": trace}
